// @ts-check
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));

/** Absolute path of the monorepo root. */
export const repoRoot = join(here, "..", "..", "..");

/** Where the generated files live, relative to the repo root. */
export const outputs = {
  gd: "apps/game/scripts/generated/palette.gd",
  css: "apps/web/src/app/tokens.css",
};

/**
 * @typedef {{ name: string, light: string, dark: string, use: string }} Token
 */

/** @returns {Token[]} */
export function loadTokens() {
  const file = join(here, "..", "tokens.json");
  return JSON.parse(readFileSync(file, "utf8")).tokens;
}

const HEADER = "GENERATED by packages/design-tokens (pnpm tokens). Do not edit by hand.";

const constName = (/** @type {string} */ name) => name.toUpperCase().replaceAll("-", "_");

/** @param {Token[]} tokens */
export function generateGdscript(tokens) {
  const dict = (/** @type {"light" | "dark"} */ theme) =>
    tokens.map((t) => `\t"${t.name}": Color("${t[theme]}"),`).join("\n");
  const vars = tokens
    .map((t) => `static var ${constName(t.name)}: Color = LIGHT["${t.name}"]`)
    .join("\n");
  const applies = tokens.map((t) => `\t${constName(t.name)} = theme["${t.name}"]`).join("\n");
  return `# ${HEADER}
class_name Palette
extends RefCounted
## Color tokens for the light and dark themes. Call apply(dark) to switch.

const LIGHT := {
${dict("light")}
}
const DARK := {
${dict("dark")}
}

${vars}


static func apply(dark: bool) -> void:
	var theme: Dictionary = DARK if dark else LIGHT
${applies}
`;
}

/** @param {Token[]} tokens */
export function generateCss(tokens) {
  const block = (/** @type {"light" | "dark"} */ theme, /** @type {string} */ indent) =>
    [`${indent}color-scheme: ${theme};`]
      .concat(tokens.map((t) => `${indent}--${t.name}: ${t[theme]};`))
      .join("\n");
  return `/* ${HEADER} */

:root {
${block("light", "  ")}
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
${block("dark", "    ")}
  }
}

:root[data-theme="dark"] {
${block("dark", "  ")}
}
`;
}

/** @param {string} hex */
function luminance(hex) {
  const [r, g, b] = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255);
  const f = (/** @type {number} */ c) => (c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4);
  return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b);
}

/**
 * WCAG contrast ratio between two #RRGGBB colors.
 * @param {string} a
 * @param {string} b
 */
export function contrast(a, b) {
  const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
}
